// teaching order; 'EXAM' exercises may use everything above them
export const WEEK_ORDER: readonly Week[] = ['W1', 'W2', 'W3', 'W4', 'W5', 'W6', 'W9', 'W10', 'EXAM']

export function weekRank(week: Week): number {
  return WEEK_ORDER.indexOf(week)
}

const STRING_LITERAL = /"(?:[^"]|"")*"/g
const QUOTED_SHEET = /'(?:[^']|'')*'/g
const CALL = /(?<![A-Za-z0-9_.$])((?:_xlfn\.|_xlws\.|_xll\.)*[A-Za-z_][A-Za-z0-9_.]*)\(/g
const PREFIX = /^(?:_xlfn\.|_xlws\.|_xll\.)+/i

// function names called in a formula, upper case, in order of first use; text in string literals and quoted
// sheet names is ignored, and the _xlfn./_xlws. storage prefixes are stripped
export function functionsUsed(formula: string): string[] {
  const body = formula.replace(STRING_LITERAL, '""').replace(QUOTED_SHEET, "''")
  const out: string[] = []
  for (const m of body.matchAll(CALL)) {
    const name = m[1].replace(PREFIX, '').toUpperCase()
    if (name && !out.includes(name)) out.push(name)
  }
  return out
}

// functions in `formula` that an exercise of `week` may not use: taught later, or never taught in the course
export function notYetTaught(formula: string, week: Week): string[] {
  const rank = weekRank(week)
  return functionsUsed(formula).filter(fn => {
    const taught = FIRST_TAUGHT[fn]
    return !taught || weekRank(taught) > rank
  })
}
